// Routes
// ===========================================================================

pub async fn list_routes(
    State(state): State<AppState>,
    _auth: AdminAuth,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    let (routes, page) = crate::admin_contract::storage::page::<db::RouteRow>(
        &state.pool,
        crate::admin_contract::storage::Collection::Routes,
        &query,
    )
    .await?;
    let accounts = db::list_accounts(&state.pool)
        .await
        .map_err(ApiError::internal)?;
    let models = db::list_models(&state.pool)
        .await
        .map_err(ApiError::internal)?;
    let mut out = Vec::new();
    for c in &routes {
        let targets = db::route_targets(&state.pool, &c.id)
            .await
            .map_err(ApiError::internal)?;
        let targets_json: Vec<Value> = targets
            .iter()
            .map(|t| {
                let model = models.iter().find(|m| m.id == t.model_id);
                let account = t.account_id.as_ref().and_then(|aid| accounts.iter().find(|a| a.id == *aid));
                json!({
                    "id": t.id,
                    "account_id": t.account_id,
                    "account_label": account.map(|a| a.label.clone()),
                    "model_id": t.model_id,
                    "model_display_name": model.map(|m| m.display_name.clone()),
                    "provider_id": model.map(|m| m.provider_id.clone()),
                    "priority": t.priority,
                    "weight": t.weight,
                    "predicate": serde_json::from_str::<Value>(&t.predicate).unwrap_or(json!({})),
                    "param_overrides": serde_json::from_str::<Value>(&t.param_overrides).unwrap_or(json!({})),
                })
            })
            .collect();
        out.push(json!({
            "id": c.id,
            "name": c.name,
            "description": c.description,
            "strategy": c.strategy,
            "fallback_triggers": serde_json::from_str::<Value>(&c.fallback_triggers).unwrap_or(json!({})),
            "portability_policy": c.portability_policy,
            "sticky_routing": c.sticky_routing != 0,
            "cache_affinity": c.cache_affinity != 0,
            "max_attempts": c.max_attempts,
            "max_concurrent_requests": c.max_concurrent_requests,
            "enabled": c.enabled != 0,
            "targets": targets_json,
        }));
    }
    Ok(Json(json!({ "routes": out, "page": page })))
}

#[derive(Deserialize, schemars::JsonSchema)]
pub struct RouteBody {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default = "priority_strategy")]
    pub strategy: String,
    #[serde(default)]
    pub fallback_triggers: Value,
    /// FR-2.11: reject | strip_with_warning.
    #[serde(default = "portability_default")]
    pub portability_policy: String,
    #[serde(default)]
    pub sticky_routing: bool,
    /// FR-7.3: cache-aware sticky routing.
    #[serde(default)]
    pub cache_affinity: bool,
    pub max_attempts: Option<i64>,
    pub max_concurrent_requests: Option<i64>,
    #[serde(default)]
    pub targets: Vec<RouteTargetBody>,
}

fn priority_strategy() -> String {
    "priority".into()
}
fn portability_default() -> String {
    "strip_with_warning".into()
}

fn route_validation_config(body: &RouteBody, id: Option<&str>) -> route_validation::RouteConfig {
    route_validation::RouteConfig {
        id: id.map(str::to_owned),
        name: body.name.clone(),
        strategy: body.strategy.clone(),
        portability_policy: body.portability_policy.clone(),
        fallback_triggers: body.fallback_triggers.clone(),
        max_attempts: body.max_attempts,
        max_concurrent_requests: body.max_concurrent_requests,
        enabled: true,
        targets: body
            .targets
            .iter()
            .map(|target| route_validation::RouteTargetConfig {
                model_id: target.model_id.clone(),
                account_id: target.account_id.clone(),
                priority: target.priority,
                weight: target.weight,
                predicate: target.predicate.clone(),
                param_overrides: target.param_overrides.clone(),
            })
            .collect(),
    }
}

fn route_validation_error(validation: &route_validation::RouteValidation) -> ApiError {
    let errors = validation
        .issues
        .iter()
        .filter(|issue| issue.severity == "error")
        .map(|issue| format!("{}: {}", issue.code, issue.message))
        .collect::<Vec<_>>()
        .join("; ");
    ApiError::fields(
        format!("Route validation failed: {errors}"),
        validation
            .issues
            .iter()
            .filter(|issue| issue.severity == "error")
            .map(|issue| crate::admin_contract::field(&issue.field, &issue.code, &issue.message))
            .collect(),
    )
}

#[derive(Clone, Deserialize, schemars::JsonSchema)]
pub struct RouteTargetBody {
    pub account_id: Option<String>,
    pub model_id: String,
    #[serde(default = "one")]
    pub priority: i64,
    #[serde(default = "one")]
    pub weight: i64,
    /// Typed eligibility predicate (FR-12.3). Empty/absent = always eligible.
    #[serde(default)]
    pub predicate: Value,
    /// Per-target parameter overrides (FR-12.2).
    #[serde(default)]
    pub param_overrides: Value,
}

fn route_write(body: &RouteBody, id: Option<&str>) -> crate::routes::RouteWrite {
    crate::routes::RouteWrite {
        config: route_validation_config(body, id),
        description: body.description.clone(),
        sticky_routing: body.sticky_routing,
        cache_affinity: body.cache_affinity,
        enabled: None,
    }
}

fn route_write_error(error: crate::routes::RouteWriteError) -> ApiError {
    use crate::routes::RouteWriteError;
    match error {
        RouteWriteError::Invalid(validation) => route_validation_error(&validation),
        RouteWriteError::NotFound(_) => ApiError::not_found(error.to_string()),
        RouteWriteError::Storage(_) | RouteWriteError::Validation(_) => ApiError::internal(error),
    }
}

