    #[tokio::test]
    async fn unbound_plugin_discovery_import_is_rejected_but_explicit_model_override_remains_supported(
    ) {
        let (state, root) = test_state("plugin-discovery-transport").await;
        let provider_id = insert_provider(
            &state,
            "native-provider",
            crate::plugins::CredentialMode::Manual,
            None,
            None,
        )
        .await;
        let legacy_model_id = insert_transport_test_model(
            &state,
            &provider_id,
            "legacy-plugin-model",
            json!({ "configured_transport": "plugin:legacy/adapter" }),
        )
        .await;
        state.registry.reload(&state.pool).await.unwrap();
        let snapshot = state.registry.snapshot();
        assert_eq!(
            crate::adapters::resolve_execution_profile(
                snapshot.providers.get(&provider_id).unwrap(),
                snapshot.models.get(&legacy_model_id).unwrap()
            )
            .unwrap()
            .transport,
            crate::adapters::TargetTransport::Plugin("plugin:legacy/adapter".into())
        );

        let error = create_model(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(provider_id.clone()),
            Json(ModelBody {
                upstream_id: "discovered-plugin-model".into(),
                display_name: None,
                enabled: true,
                context_window: None,
                max_output_tokens: None,
                capabilities: json!({}),
                prices: json!({}),
                parameters: json!({}),
                thinking_map: ThinkingMap::default(),
                extra_request: json!({}),
                discovery: json!({
                    "imported_from_discovery": true,
                    "execution_supported": true,
                    "transport": { "format": "plugin:other/adapter" }
                }),
                transport_override: None,
            }),
        )
        .await
        .unwrap_err();
        assert_eq!(error.0, StatusCode::BAD_REQUEST);
        assert!(error.1.contains("discovered plugin model transport"));
        let models = db::models_for_provider(&state.pool, &provider_id)
            .await
            .unwrap();
        assert_eq!(models.len(), 1);
        assert_eq!(models[0].upstream_id, "legacy-plugin-model");

        let created = create_model(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(provider_id.clone()),
            Json(ModelBody {
                upstream_id: "explicit-plugin-model".into(),
                display_name: None,
                enabled: true,
                context_window: None,
                max_output_tokens: None,
                capabilities: json!({}),
                prices: json!({}),
                parameters: json!({}),
                thinking_map: ThinkingMap::default(),
                extra_request: json!({}),
                discovery: json!({
                    "imported_from_discovery": true,
                    "execution_supported": true
                }),
                transport_override: Some("plugin:other/adapter".into()),
            }),
        )
        .await
        .unwrap();
        let model_id = created.0["id"].as_str().unwrap();
        let snapshot = state.registry.snapshot();
        assert_eq!(
            crate::adapters::resolve_execution_profile(
                snapshot.providers.get(&provider_id).unwrap(),
                snapshot.models.get(model_id).unwrap()
            )
            .unwrap()
            .transport,
            crate::adapters::TargetTransport::Plugin("plugin:other/adapter".into())
        );

        let reconciliation_model_id = insert_transport_test_model(
            &state,
            &provider_id,
            "reconciliation-plugin-model",
            json!({}),
        )
        .await;
        db::merge_model_discovery(
            &state.pool,
            &reconciliation_model_id,
            &json!({
                "latest_observation": {
                    "transport": { "format": "plugin:other/adapter" }
                },
                "reconciliation": { "diff": [{ "field": "transport" }] }
            }),
        )
        .await
        .unwrap();
        let _ = update_model_reconciliation(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(reconciliation_model_id.clone()),
            Json(ReconciliationActionBody {
                action: "accept".into(),
                fields: vec!["transport".into()],
            }),
        )
        .await
        .unwrap();
        let reconciliation_model = db::get_model(&state.pool, &reconciliation_model_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            discovery_object(&reconciliation_model)["configured_transport"],
            "plugin:other/adapter"
        );
        let snapshot = state.registry.snapshot();
        assert_eq!(
            crate::adapters::resolve_execution_profile(
                snapshot.providers.get(&provider_id).unwrap(),
                snapshot.models.get(&reconciliation_model_id).unwrap()
            )
            .unwrap()
            .transport,
            crate::adapters::TargetTransport::Plugin("plugin:other/adapter".into())
        );

        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn legacy_cached_discovery_import_uses_original_observation_time() {
        let (state, root) = test_state("legacy-discovery-import").await;
        let provider_id = "provider-legacy-discovery";
        sqlx::query(
            "INSERT INTO providers (id, name, base_url, wire_format, auth_scheme, created_at)
             VALUES (?, 'Provider', 'https://example.test', 'openai', 'bearer', ?)",
        )
        .bind(provider_id)
        .bind(db::now_iso())
        .execute(&state.pool)
        .await
        .unwrap();
        let discovery_observed_at = db::now_iso();
        persist_provider_discovery_observations(
            &state.pool,
            provider_id,
            &json!({
                "models": [{
                    "id": "legacy-cache-model",
                    "display_name": "Legacy Cache Model",
                    "context_window": 4096,
                    "capabilities": {"text": true},
                    "execution_supported": true,
                    "reconciliation": {
                        "status": "unchanged",
                        "checked_at": discovery_observed_at,
                        "last_success_at": discovery_observed_at,
                        "diff": [],
                        "pinned_fields": []
                    }
                }],
                "disappeared": []
            }),
        )
        .await
        .unwrap();

        let cached = cached_model_discovery(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(provider_id.into()),
        )
        .await
        .unwrap();
        let cached_model = &cached.0["models"][0];
        assert!(cached_model.get("observed_at").is_none());
        assert_eq!(
            cached_model["reconciliation"]["last_success_at"],
            discovery_observed_at
        );
        let mut discovery = json!({
            "context_window": cached_model["context_window"],
            "capabilities": cached_model["capabilities"],
            "execution_supported": cached_model["execution_supported"],
            "imported_from_discovery": true
        });
        let observed_at = cached_model
            .get("observed_at")
            .filter(|value| !value.is_null())
            .or_else(|| {
                cached_model
                    .pointer("/reconciliation/last_success_at")
                    .filter(|value| !value.is_null())
            })
            .or_else(|| {
                cached_model
                    .pointer("/reconciliation/checked_at")
                    .filter(|value| !value.is_null())
            });
        if let Some(observed_at) = observed_at {
            discovery["observed_at"] = observed_at.clone();
        }
        assert_eq!(discovery["observed_at"], discovery_observed_at);
        let result = create_model(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(provider_id.into()),
            Json(ModelBody {
                upstream_id: cached_model["id"].as_str().unwrap().into(),
                display_name: cached_model["display_name"].as_str().map(str::to_string),
                enabled: true,
                context_window: cached_model["context_window"].as_i64(),
                max_output_tokens: None,
                capabilities: cached_model["capabilities"].clone(),
                prices: json!({}),
                parameters: json!({}),
                thinking_map: ThinkingMap::default(),
                extra_request: json!({}),
                discovery,
                transport_override: None,
            }),
        )
        .await;
        let created = result.unwrap_or_else(|error| {
            panic!("legacy cached model import failed: {error:?}");
        });
        let model_id = created.0["id"].as_str().unwrap();
        assert!(db::get_model(&state.pool, model_id)
            .await
            .unwrap()
            .is_some());
        let observations = db::list_model_observations(&state.pool, model_id, 10, None)
            .await
            .unwrap();
        assert_eq!(observations.len(), 1);
        let expected_observed_at = chrono::DateTime::parse_from_rfc3339(&discovery_observed_at)
            .unwrap()
            .with_timezone(&chrono::Utc)
            .to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
        assert_eq!(observations[0].observed_at, expected_observed_at);

        state.pool.close().await;
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn malformed_import_observations_are_rejected_before_model_creation() {
        let (state, root) = test_state("invalid-observation-import").await;
        let provider_id = "provider-invalid-observation-import";
        sqlx::query(
            "INSERT INTO providers (id, name, base_url, wire_format, auth_scheme, created_at)
             VALUES (?, 'Provider', 'https://example.test', 'openai', 'bearer', ?)",
        )
        .bind(provider_id)
        .bind(db::now_iso())
        .execute(&state.pool)
        .await
        .unwrap();

        let cases = [
            (
                "invalid-observed-at-string",
                json!({
                    "imported_from_discovery": true,
                    "execution_supported": true,
                    "observed_at": "not-a-date"
                }),
            ),
            (
                "invalid-observed-at-number",
                json!({
                    "imported_from_discovery": true,
                    "execution_supported": true,
                    "observed_at": 123
                }),
            ),
            (
                "invalid-latest-observation-shape",
                json!({
                    "imported_from_discovery": true,
                    "execution_supported": true,
                    "latest_observation": "invalid"
                }),
            ),
        ];
        for (upstream_id, discovery) in cases {
            let result = create_model(
                State(state.clone()),
                AdminAuth {
                    actor: "admin".into(),
                    token: "test".into(),
                },
                Path(provider_id.into()),
                Json(ModelBody {
                    upstream_id: upstream_id.into(),
                    display_name: None,
                    enabled: true,
                    context_window: None,
                    max_output_tokens: None,
                    capabilities: json!({}),
                    prices: json!({}),
                    parameters: json!({}),
                    thinking_map: ThinkingMap::default(),
                    extra_request: json!({}),
                    discovery,
                    transport_override: None,
                }),
            )
            .await;
            let error = match result {
                Ok(_) => panic!("malformed discovery for {upstream_id} was accepted"),
                Err(error) => error,
            };

            assert_eq!(error.0, StatusCode::BAD_REQUEST, "{upstream_id}");
            assert!(
                db::find_model_by_upstream(&state.pool, provider_id, upstream_id)
                    .await
                    .unwrap()
                    .is_none(),
                "malformed discovery for {upstream_id} created a model"
            );
        }

        state.pool.close().await;
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn model_observations_endpoint_paginates_and_keeps_deleted_model_history() {
        let (state, root) = test_state("model-observations").await;
        let provider_id = "provider-observations-api";
        sqlx::query(
            "INSERT INTO providers (id, name, base_url, wire_format, auth_scheme, created_at)
             VALUES (?, 'Provider', 'https://example.test', 'openai', 'bearer', ?)",
        )
        .bind(provider_id)
        .bind(db::now_iso())
        .execute(&state.pool)
        .await
        .unwrap();
        let model_id = db::insert_model(
            &state.pool,
            &db::NewModel {
                provider_id,
                upstream_id: "model",
                display_name: "Model",
                enabled: true,
                context_window: None,
                max_output_tokens: None,
                capabilities: json!({}),
                prices: json!({}),
                parameters: json!({}),
                thinking_map: json!({}),
                extra_request: json!({}),
                discovery: json!({}),
            },
        )
        .await
        .unwrap();
        let row = db::get_model(&state.pool, &model_id)
            .await
            .unwrap()
            .unwrap();
        for observed_at in ["2026-09-01T00:00:00Z", "2026-09-02T00:00:00Z"] {
            persist_model_discovery_update(
                &state.pool,
                &row,
                json!({
                    "latest_observation": {
                        "observed_at": observed_at,
                        "context_window": null,
                        "capability_sources": {}
                    }
                }),
            )
            .await
            .unwrap();
        }
        let scope = json!({
            "provider_id": provider_id,
            "account_id": "account-a",
            "model_id": model_id,
            "transport": "openai"
        });
        for (probe_key, verified_at) in [
            ("tool_calling", "2026-09-03T00:00:00Z"),
            ("structured_output", "2026-09-04T00:00:00Z"),
        ] {
            persist_probe_evidence_observation(
                &state.pool,
                provider_id,
                &model_id,
                probe_key.into(),
                json!({
                    "status": "supported",
                    "value": null,
                    "verified_at": verified_at,
                    "fresh_until": "2999-01-01T00:00:00Z",
                    "scope": scope
                }),
            )
            .await
            .unwrap();
        }
        let history = list_model_observations(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(model_id.clone()),
            Query(ModelObservationsQuery {
                limit: Some(10),
                cursor: None,
            }),
        )
        .await
        .unwrap();
        let probe_keys: Vec<_> = history.0["observations"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|row| row["kind"] == "capability_probe")
            .map(|row| row["value"]["capability"].as_str().unwrap())
            .collect();
        assert_eq!(probe_keys, ["structured_output", "tool_calling"]);

        let first_page = list_model_observations(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(model_id.clone()),
            Query(ModelObservationsQuery {
                limit: Some(1),
                cursor: None,
            }),
        )
        .await
        .unwrap();
        assert_eq!(first_page.0["observations"].as_array().unwrap().len(), 1);
        let cursor = first_page.0["next_cursor"].as_str().unwrap().to_string();
        assert_eq!(
            first_page.0["observations"][0]["value"]["capability"],
            "structured_output"
        );
        assert!(first_page.0["observations"][0].get("scope").is_some());
        assert!(first_page.0["observations"][0].get("value").is_some());

        persist_model_discovery_update(
            &state.pool,
            &row,
            json!({
                "latest_observation": {
                    "observed_at": "2026-09-05T00:00:00Z",
                    "capability_sources": {}
                }
            }),
        )
        .await
        .unwrap();
        let second_page = list_model_observations(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(model_id.clone()),
            Query(ModelObservationsQuery {
                limit: Some(1),
                cursor: Some(cursor),
            }),
        )
        .await
        .unwrap();
        assert_eq!(second_page.0["observations"].as_array().unwrap().len(), 1);
        assert_eq!(
            second_page.0["observations"][0]["value"]["capability"],
            "tool_calling"
        );
        assert_ne!(
            first_page.0["observations"][0]["id"], second_page.0["observations"][0]["id"],
            "appending a row between pages must not duplicate earlier history"
        );

        db::delete_model(&state.pool, &model_id).await.unwrap();
        let retained = list_model_observations(
            State(state.clone()),
            AdminAuth {
                actor: "admin".into(),
                token: "test".into(),
            },
            Path(model_id),
            Query(ModelObservationsQuery {
                limit: Some(10),
                cursor: None,
            }),
        )
        .await
        .unwrap();
        assert_eq!(retained.0["observations"].as_array().unwrap().len(), 5);

        state.pool.close().await;
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn unregistering_plugin_resets_routing_work_state_and_flights() {
        use tokio::sync::{Notify, Semaphore};

        let (state, root) = test_state("plugin-routing-work-unregister").await;
        let plugin_id = "routing-plugin";
        let scope = format!("plugin:{plugin_id}");
        let old_identity = state.provider_work.activate_auxiliary_scope(&scope);
        let old_started = Arc::new(Notify::new());
        let release_old = Arc::new(Semaphore::new(0));
        let old_coordinator = state.provider_work.clone();
        let old_flight_identity = old_identity.clone();
        let old_started_task = old_started.clone();
        let release_old_task = release_old.clone();
        let old_flight = tokio::spawn(async move {
            old_coordinator
                .coalesce(
                    old_flight_identity,
                    crate::provider_work::ProviderWorkClass::RoutingFactsRefresh,
                    "cached_snapshot".into(),
                    move || async move {
                        old_started_task.notify_one();
                        release_old_task.acquire_owned().await.unwrap().forget();
                        Ok::<_, String>("old-generation".to_owned())
                    },
                )
                .await
        });
        tokio::time::timeout(std::time::Duration::from_secs(1), old_started.notified())
            .await
            .expect("routing refresh should be in flight");

        state
            .provider_work
            .acquire(
                old_identity.clone(),
                crate::provider_work::ProviderWorkClass::RoutingFactsRefresh,
            )
            .await
            .unwrap()
            .finish_failure(Some(
                crate::provider_work::ProviderBackoffEvidence::Transient {
                    retry_after_secs: Some(30),
                },
            ))
            .await;
        assert!(matches!(
            state
                .provider_work
                .acquire(
                    old_identity.clone(),
                    crate::provider_work::ProviderWorkClass::RoutingFactsRefresh,
                )
                .await,
            Err(crate::provider_work::ProviderWorkAcquireError::BackedOff(_))
        ));

        state.unregister_plugin_capabilities(plugin_id);
        let state_after_unregister = state.provider_work.state_counts();
        let old_generation_invalidated = !old_identity.is_current();
        let new_identity = state.provider_work.activate_auxiliary_scope(&scope);
        let generation_changed = !Arc::ptr_eq(
            &old_identity.provider_generation,
            &new_identity.provider_generation,
        );
        let fresh_admission = state
            .provider_work
            .acquire(
                new_identity.clone(),
                crate::provider_work::ProviderWorkClass::RoutingFactsRefresh,
            )
            .await;
        let fresh_gate = fresh_admission.is_ok();
        if let Ok(permit) = fresh_admission {
            permit.finish_success().await;
        }

        let new_runs = Arc::new(AtomicUsize::new(0));
        let new_runs_task = new_runs.clone();
        let new_coordinator = state.provider_work.clone();
        let new_flight = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            new_coordinator.coalesce(
                new_identity,
                crate::provider_work::ProviderWorkClass::RoutingFactsRefresh,
                "cached_snapshot".into(),
                move || async move {
                    new_runs_task.fetch_add(1, Ordering::Relaxed);
                    Ok::<_, String>("new-generation".to_owned())
                },
            ),
        )
        .await;

        release_old.add_permits(1);
        let old_result = tokio::time::timeout(std::time::Duration::from_secs(1), old_flight)
            .await
            .expect("old routing refresh should finish after release")
            .unwrap()
            .unwrap();
        assert_eq!(&*old_result, "old-generation");
        assert_eq!(
            state_after_unregister,
            (0, 0),
            "unregistering capabilities must evict the synthetic provider gate and flight"
        );
        assert!(
            old_generation_invalidated,
            "unregistration invalidates work holding the previous generation"
        );
        assert!(
            generation_changed,
            "re-enabled plugin gets a fresh generation"
        );
        assert!(
            fresh_gate,
            "new generation must not inherit provider backoff"
        );
        let new_result = new_flight
            .expect("new generation must not join the old flight")
            .expect("new generation routing refresh should succeed");
        assert_eq!(&*new_result, "new-generation");
        assert_eq!(new_runs.load(Ordering::Relaxed), 1);

        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn queued_plugin_routing_refresh_cannot_recreate_scope_after_unregister() {
        let (state, root) = test_state("queued-plugin-routing-work-unregister").await;
        let plugin_id = "queued-routing-plugin";
        let scope = format!("plugin:{plugin_id}");
        state.provider_work.activate_auxiliary_scope(&scope);

        let queued_coordinator = state.provider_work.clone();
        let queued_scope = scope.clone();
        let executions = Arc::new(AtomicUsize::new(0));
        let queued_executions = executions.clone();
        let (queued_tx, queued_rx) = tokio::sync::oneshot::channel();
        let (resume_tx, resume_rx) = tokio::sync::oneshot::channel();
        let queued_job = tokio::spawn(async move {
            let _ = queued_tx.send(());
            resume_rx.await.unwrap();
            let Some(identity) = queued_coordinator.auxiliary_identity(&queued_scope) else {
                return Err(Arc::new(crate::provider_work::ProviderWorkError::Aborted));
            };
            queued_coordinator
                .run(
                    identity,
                    crate::provider_work::ProviderWorkClass::RoutingFactsRefresh,
                    Some("cached_snapshot".into()),
                    move || async move {
                        queued_executions.fetch_add(1, Ordering::Relaxed);
                        Err::<(), _>("plugin was disabled before refresh started".to_owned())
                    },
                    |_| None,
                )
                .await
        });
        queued_rx.await.unwrap();

        state.unregister_plugin_capabilities(plugin_id);
        assert_eq!(state.provider_work.state_counts(), (0, 0));
        resume_tx.send(()).unwrap();
        let result = queued_job.await.unwrap();

        assert!(
            matches!(
                result,
                Err(error)
                    if matches!(
                        error.as_ref(),
                        crate::provider_work::ProviderWorkError::Aborted
                    )
            ),
            "queued refresh must not acquire a new identity after unregister"
        );
        assert_eq!(executions.load(Ordering::Relaxed), 0);
        assert_eq!(state.provider_work.state_counts(), (0, 0));
        assert_eq!(state.provider_work.metrics_snapshot().scheduled, 0);

        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

