    #[tokio::test]
    async fn deletion_between_validation_and_coordinator_admission_rejects_lifecycle_work() {
        let (state, root) = test_state("delete-before-provider-work-admission").await;
        let provider_id = insert_provider(
            &state,
            "delete-before-provider-work-admission",
            crate::plugins::CredentialMode::Manual,
            None,
            None,
        )
        .await;
        state.registry.reload(&state.pool).await.unwrap();

        assert!(db::get_provider(&state.pool, &provider_id)
            .await
            .unwrap()
            .is_some());
        let identity = state
            .provider_work_identity(&provider_id, None)
            .expect("provider validation should capture its active generation");
        let validated = Arc::new(Barrier::new(2));
        let resume = Arc::new(Barrier::new(2));
        let work_state = state.clone();
        let work_validated = validated.clone();
        let work_resume = resume.clone();
        let work = tokio::spawn(async move {
            work_validated.wait().await;
            work_resume.wait().await;
            let executions = Arc::new(AtomicUsize::new(0));
            let invoked = executions.clone();
            let result = work_state
                .provider_work
                .coalesce(
                    identity,
                    crate::provider_work::ProviderWorkClass::ModelDiscovery,
                    "reconciliation".into(),
                    move || async move {
                        invoked.fetch_add(1, Ordering::Relaxed);
                        Ok::<_, String>(())
                    },
                )
                .await;
            (result, executions.load(Ordering::Relaxed))
        });

        validated.wait().await;
        let _ = delete_provider(
            axum::extract::State(state.clone()),
            auth(),
            Path(provider_id.clone()),
        )
        .await
        .unwrap();
        resume.wait().await;

        let (result, executions) = work.await.unwrap();
        assert!(matches!(
            result,
            Err(error)
                if matches!(
                    error.as_ref(),
                    crate::provider_work::ProviderWorkError::Aborted
                )
        ));
        assert_eq!(executions, 0, "deleted lifecycle work must not start");
        assert_eq!(state.provider_work.metrics_snapshot().scheduled, 0);
        assert_eq!(state.provider_work.state_counts(), (0, 0));

        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn account_and_provider_deletion_evict_control_plane_state() {
        let (state, root) = test_state("delete-control-plane-state").await;
        let spy = Arc::new(CredentialEvictionSpy::default());
        state.register_plugin_credential_strategy("test-eviction", spy.clone());

        let account_provider_id = insert_provider(
            &state,
            "delete-account-provider",
            crate::plugins::CredentialMode::Manual,
            None,
            None,
        )
        .await;
        let encrypted = state.crypto.encrypt("account-secret").unwrap();
        let account_id = db::insert_account(
            &state.pool,
            &account_provider_id,
            "account-to-delete",
            &encrypted,
            "test-key",
            1,
            1,
            None,
            "none",
        )
        .await
        .unwrap();
        let scheduled = crate::credentials::ResolvedCredential {
            metadata: crate::credentials::CredentialMetadata::default(),
            secret: "schedule-secret".into(),
            expires_at: Some((chrono::Utc::now() + chrono::Duration::hours(1)).to_rfc3339()),
            refresh_after: Some((chrono::Utc::now() + chrono::Duration::minutes(10)).to_rfc3339()),
            rotated: false,
        };
        state
            .credential_refresh
            .observe(&account_provider_id, &account_id, &scheduled);
        drop(
            state
                .provider_work
                .acquire(
                    &account_provider_id,
                    crate::provider_work::ProviderWorkClass::HealthProbe,
                )
                .await
                .unwrap(),
        );

        let Json(account_result) = delete_account(
            axum::extract::State(state.clone()),
            auth(),
            Path(account_id.clone()),
        )
        .await
        .unwrap();
        assert_eq!(account_result["ok"], true);
        assert!(db::get_account(&state.pool, &account_id)
            .await
            .unwrap()
            .is_none());
        assert!(state
            .credential_refresh
            .next_attempt_at(&account_provider_id, &account_id)
            .is_none());
        assert!(spy
            .accounts
            .lock()
            .contains(&(account_provider_id.clone(), account_id.clone())));

        let provider_id = insert_provider(
            &state,
            "delete-provider",
            crate::plugins::CredentialMode::Manual,
            None,
            None,
        )
        .await;
        let encrypted = state.crypto.encrypt("provider-account-secret").unwrap();
        let provider_account_id = db::insert_account(
            &state.pool,
            &provider_id,
            "provider-account",
            &encrypted,
            "test-key",
            1,
            1,
            None,
            "none",
        )
        .await
        .unwrap();
        state
            .credential_refresh
            .observe(&provider_id, &provider_account_id, &scheduled);
        state
            .provider_work
            .acquire(
                &provider_id,
                crate::provider_work::ProviderWorkClass::HealthProbe,
            )
            .await
            .unwrap()
            .finish_failure(Some(
                crate::provider_work::ProviderBackoffEvidence::Transient {
                    retry_after_secs: None,
                },
            ))
            .await;
        assert!(state
            .provider_work
            .acquire(
                &provider_id,
                crate::provider_work::ProviderWorkClass::HealthProbe
            )
            .await
            .is_err());

        let Json(provider_result) = delete_provider(
            axum::extract::State(state.clone()),
            auth(),
            Path(provider_id.clone()),
        )
        .await
        .unwrap();
        assert_eq!(provider_result["ok"], true);
        assert!(db::get_provider(&state.pool, &provider_id)
            .await
            .unwrap()
            .is_none());
        assert!(state
            .credential_refresh
            .next_attempt_at(&provider_id, &provider_account_id)
            .is_none());
        assert!(spy.providers.lock().contains(&provider_id));
        assert!(matches!(
            state
                .provider_work
                .acquire(
                    &provider_id,
                    crate::provider_work::ProviderWorkClass::HealthProbe
                )
                .await,
            Err(crate::provider_work::ProviderWorkAcquireError::Aborted)
        ));

        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

    #[tokio::test]
    async fn model_update_keeps_effective_price_when_version_persistence_fails() {
        let (state, root) = test_state("model-price-rollback").await;
        let provider_id = insert_provider(
            &state,
            "pricing-provider",
            crate::plugins::CredentialMode::Manual,
            None,
            None,
        )
        .await;
        let old_prices = Prices {
            input_per_1m: Some(1.0),
            output_per_1m: Some(2.0),
            ..Prices::default()
        };
        let model_id = db::insert_model(
            &state.pool,
            &db::NewModel {
                provider_id: &provider_id,
                upstream_id: "priced-model",
                display_name: "Priced Model",
                enabled: true,
                context_window: None,
                max_output_tokens: None,
                capabilities: json!({}),
                prices: serde_json::to_value(&old_prices).unwrap(),
                parameters: json!({}),
                thinking_map: json!({}),
                extra_request: json!({}),
                discovery: json!({}),
            },
        )
        .await
        .unwrap();
        let old_version = db::commit_effective_model_pricing(
            &state.pool,
            &model_id,
            &old_prices,
            "operator",
            &json!({"configured_by": "test"}),
        )
        .await
        .unwrap()
        .unwrap();

        sqlx::query(
            "CREATE TRIGGER reject_model_price_version_insert
             BEFORE INSERT ON price_versions
             BEGIN
                 SELECT RAISE(ABORT, 'injected price version persistence failure');
             END",
        )
        .execute(&state.pool)
        .await
        .unwrap();

        let result = update_model(
            State(state.clone()),
            auth(),
            Path(model_id.clone()),
            Json(ModelBody {
                upstream_id: "priced-model".into(),
                display_name: Some("Changed Model Name".into()),
                enabled: true,
                context_window: Some(200_000),
                max_output_tokens: Some(16_384),
                capabilities: json!({}),
                prices: json!({
                    "input_per_1m": 9.0,
                    "output_per_1m": 18.0
                }),
                parameters: json!({}),
                thinking_map: ThinkingMap::default(),
                extra_request: json!({}),
                discovery: json!({}),
                transport_override: None,
            }),
        )
        .await;

        assert!(result.is_err());
        let row = db::get_model(&state.pool, &model_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.display_name, "Priced Model");
        assert_eq!(row.context_window, None);
        assert_eq!(row.max_output_tokens, None);
        assert_eq!(row.prices().input_per_1m, Some(1.0));
        assert_eq!(row.prices().output_per_1m, Some(2.0));
        let discovery: Value = serde_json::from_str(&row.discovery).unwrap();
        assert_eq!(
            discovery
                .pointer("/effective_pricing/price_version_id")
                .and_then(Value::as_str),
            Some(old_version.as_str())
        );

        drop(state);
        let _ = std::fs::remove_dir_all(root);
    }

