        none_provider["credential_plugin"] = json!("plugin:plugin.test/strategy");
        let none_error = import_config(
            State(state.clone()),
            auth(),
            Json(ImportBody {
                config: json!({"providers": [none_provider]}),
                apply: true,
            }),
        )
        .await
        .unwrap_err();
